package com.way2jobs.notification.service.impl;
import com.way2jobs.notification.dto.NotificationResponse; import com.way2jobs.notification.entity.Notification; import com.way2jobs.notification.repository.NotificationRepository; import com.way2jobs.notification.service.NotificationService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class NotificationServiceImpl implements NotificationService {private final NotificationRepository repository; public Page<NotificationResponse> getNotifications(int page,int size){return repository.findAllByOrderByCreatedAtDesc(PageRequest.of(Math.max(page,0),Math.max(size,1))).map(this::map);} public long unreadCount(LocalDateTime since){return repository.countByCreatedAtAfter(since);} private NotificationResponse map(Notification n){return NotificationResponse.builder().id(n.getId()).title(n.getTitle()).body(n.getBody()).jobId(n.getJob()==null?null:n.getJob().getId()).type(n.getType()).createdAt(n.getCreatedAt()).build();}}
